#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_dtype;
uniform float amzp_softness;
uniform float amzp_noiseSize;
uniform float amzp_seed;
uniform float amzp_glow;
uniform float amzp_radius;
uniform float amzp_threshold;
layout(color) uniform half4 amzp_glowColor;
uniform float amzp_glowEdge;
uniform float amzp_quality;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float qMul() { return amzp_quality < 1.5 ? 0.25 : (amzp_quality < 2.5 ? 0.5 : (amzp_quality < 3.5 ? 1.0 : (amzp_quality < 4.5 ? 1.5 : 2.0))); }
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.91) * 43758.5453); }
    float vnoise(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hh(i), hh(i + float2(1.0, 0.0)), f.x), mix(hh(i + float2(0.0, 1.0)), hh(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float fbm(float2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + 11.7; a *= 0.5; } return v; }
    float4 mixed(float2 uv, float t, out float edge) {
        float4 a = amzTexture(0, l2s(uv));
        float4 b = amzTexture(1, l2s(uv));
        float f = t;
        edge = 0.0;
        if (int(amzp_dtype) != 0) {
            float key;
            if (int(amzp_dtype) == 1) key = a.a > 0.0001 ? 1.0 - dot(a.rgb / a.a, float3(0.299, 0.587, 0.114)) : 1.0;
            else {
                float2 q = advRot((uv - 0.5) * layer, radians(amzp_advAngle)) / (min(layer.x, layer.y) * max(amzp_noiseSize * amzp_advScale, 0.01));
                key = fbm(q * 5.0);
            }
            float s = max(amzp_softness, 0.001) * 0.5;
            float e = mix(-s, 1.0 + s, t);
            f = 1.0 - smoothstep(key - s, key + s, e);
            f = 1.0 - f;
            edge = 1.0 - abs(f * 2.0 - 1.0);
        }
        return mix(a, b, clamp(f, 0.0, 1.0));
    }
    float3 bright(float4 c) {
        if (c.a <= 0.0001) return float3(0.0);
        float3 u = c.rgb / c.a;
        float l = dot(u, float3(0.299, 0.587, 0.114));
        float th = clamp(amzp_threshold, 0.0, 0.999);
        return u * max(l - th, 0.0) / (1.0 - th) * c.a;
    }
    void amzRender() {
        float2 uv = amzLayerNorm();
        float t = clamp(prog(amzp_completion), 0.0, 1.0);
        float edge;
        float4 base = mixed(uv, t, edge);
        float peak = sin(3.14159265 * t);
        float3 amzSource_gl = float3(0.0);
        float r = max(amzp_radius, 0.0) * pxs() * max(amzp_advScale, 0.01);
        if (peak > 0.001 && amzp_glow > 0.0 && r > 0.5) {
            float wsum = 0.0;
            float nq = max(6.0, floor(24.0 * qMul() + 0.5));
            for (int i = 0; i < 48; i++) {
                if (float(i) >= nq) break;
                float fi = float(i) + 0.5;
                float a = fi * 2.39996;
                float rr = r * sqrt(fi / nq);
                float2 o = float2(cos(a), sin(a)) * rr / layer;
                float e2;
                float4 c = mixed(clamp(uv + o, 0.0, 1.0), t, e2);
                float w = 1.0 - 0.6 * fi / nq;
                amzSource_gl += bright(c) * w;
                wsum += w;
            }
            amzSource_gl /= max(wsum, 1e-4);
        }
        float3 L = (amzSource_gl * 2.2 + bright(base) * 0.6) * amzp_glow * peak * amzp_glowColor.rgb;
        L += amzp_glowColor.rgb * edge * amzp_glowEdge * 0.8 * base.a;
        float3 bu = base.a > 0.0001 ? base.rgb / base.a : float3(0.0);
        bu = bu + (1.0 - bu) * (1.0 - exp(-L * 1.4));
        float4 o = float4(bu * base.a, base.a);
        o = clamp(o, 0.0, 1.0);
        amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
